import React, { useState } from "react";
import { auth, database } from "../firebase"; // Import Firebase auth and database
// signInWithPopup, GoogleAuthProvider, 
import { signInWithEmailAndPassword } from "firebase/auth"; // Firebase auth methods
import { ref, push } from "firebase/database"; // Firebase Realtime Database methods
//import googleLogo from "../assets/google-logo.png";
import emailLogo from "../assets/email-logo.png"; // Add an email ico
import "./Auth.css"; // Import the CSS file


const Auth = ({ onSignIn }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [failedAttempts, setFailedAttempts] = useState(0);

  // // Function to handle Google sign-in
  // const handleSignInWithGoogle = () => {
  //   const provider = new GoogleAuthProvider();

  //   signInWithPopup(auth, provider)
  //     .then((userCredential) => {
  //       setError("");
  //       setFailedAttempts(0);
  //       onSignIn(userCredential.user);
  //     })
  //     .catch((err) => {
  //       setError("Failed to sign in with Google. Please try again.");
  //       handleFailedAttempt(err.email || "unknown");
  //     });
  // };

  // Function to handle email/password sign-in
  const handleSignInWithEmail = () => {
    signInWithEmailAndPassword(auth, email, password)
      .then((userCredential) => {
        setError("");
        setFailedAttempts(0);
        onSignIn(userCredential.user);
      })
      .catch((err) => {
        setError("Invalid credentials. Please try again.");
        handleFailedAttempt(email);
      });
  };

  // Function to send an alert to Firebase after 3 failed attempts
  const handleFailedAttempt = (userEmail) => {
    setFailedAttempts((prev) => prev + 1);

    if (failedAttempts + 1 >= 3) {
      const alertRef = ref(database, "alerts/failedLogins");
      const alertData = {
        email: userEmail,
        timestamp: new Date().toISOString(),
        message: "User has failed to log in 3 consecutive times.",
      };

      push(alertRef, alertData)
        .then(() => console.log("Alert sent to Firebase successfully."))
        .catch((error) => console.error("Error sending alert to Firebase:", error));
    }
  };

  return (
    <div style={{ textAlign: "center" }}>
      <h2>Sign In</h2>
      
      {/* Google Sign-In Button
      <button className="google-sign-in" onClick={handleSignInWithGoogle}>
        <img src={googleLogo} alt="Google Logo" className="google-logo" />
        Sign in with Google
      </button>

      <div>OR</div> */}

      {/* Email/Password Sign-In Form */}
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        style={{ display: "block", margin: "10px auto" }}
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        style={{ display: "block", margin: "10px auto" }}
      />
      <button className="email-sign-in" onClick={handleSignInWithEmail}>
        <img src={emailLogo} alt="Email Icon" className="email-logo" />
        Sign in with Email
      </button>
      {/* Error Message */}
      {error && <div style={{ color: "red", marginTop: "10px" }}>{error}</div>}
    </div>
  );
};

export default Auth;
