import React, { useEffect, useState } from "react";
import { database } from "../firebase";
import { ref, onValue } from "firebase/database";
import { getAuth, signOut } from "firebase/auth";

const ScannedData = ({ user, onStartScan }) => {
  const [scans, setScans] = useState([]);
  const [selectedData, setSelectedData] = useState(null); // State to store the clicked QR data
  const [isModalOpen, setIsModalOpen] = useState(false); // State to control modal visibility


  useEffect(() => {
    const userPath = user.email.replace(".", "-");
    const scanRef = ref(database, `data/scans/${userPath}`);

    // Real-time listener using onValue
    const unsubscribe = onValue(scanRef, (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        const entries = Object.entries(data).map(([key, value]) => ({
          ...value,
          key,
        }));

        // Sort the scans in descending order based on timestamp
        const sortedEntries = entries.sort((a, b) => b.timestamp - a.timestamp);
        setScans(sortedEntries); // Update state with real-time data
      } else {
        setScans([]); // No data case
      }
    });

    // Cleanup the listener when the component unmounts
    return () => unsubscribe();
  }, [user]);

  useEffect(() => {
    const userPath = user.email.replace(".", "-");
    const scanRef = ref(database, `data/scans/${userPath}`);

    // Function to fetch data from Firebase
    const fetchData = () => {
      onValue(scanRef, (snapshot) => {
        if (snapshot.exists()) {
          const data = snapshot.val();
          const entries = Object.entries(data).map(([key, value]) => ({
            ...value,
            key,
          }));
          const sortedEntries = entries.sort((a, b) => b.timestamp - a.timestamp);
          setScans(sortedEntries);
          // Save data to localStorage
          localStorage.setItem(`scans_${userPath}`, JSON.stringify(sortedEntries));
        } else {
          setScans([]);
          localStorage.removeItem(`scans_${userPath}`);
        }
      });
    };

    // Load data from localStorage on component mount
    const cachedData = localStorage.getItem(`scans_${userPath}`);
    if (cachedData) {
      setScans(JSON.parse(cachedData));
    }

    // Fetch data from Firebase
    fetchData();

    // Cleanup function
    return () => {
      // Unsubscribe from Firebase listener if needed
    };
  }, [user]);

  // Truncate the QR code to the first 10 characters
  const truncateQRCode = (data) => {
    try {
      return data.length > 10 ? data.slice(0, 10) + "..." : data;
    } catch (error) {
      console.error("Error in truncateQRCode: ", error);
      return ""; // Return an empty string if an error occurs
    }
  };

  // Truncate latitude and longitude for table view (using string slicing)
  const truncateCoordinates = (coordinate) => {
    const str = coordinate.toString();
    return str.substring(0, str.indexOf(".") + 3); // Keep 5 decimal places
  };

  const handleRowClick = (data) => {
    setSelectedData(data); // Set the clicked row data
  };

  const handleSignOut = async () => {
    const auth = getAuth();
    try {
      await signOut(auth);
      window.location.reload();
    } catch (error) {
      console.error("Error signing out:", error.message);
    }
  };

  return (
    <div>
      <h2 style={{ textAlign: "center" }}>Scanned Data</h2>

      {/* Buttons */}
      <div style={{ position: "relative", marginBottom: "10px" }}>
        <button
          onClick={onStartScan}
          style={{
            position: "absolute",
            top: -70,
            left: 10,
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "5px 10px",
            cursor: "pointer",
          }}
        >
          Add Scan
        </button>
        <button
          onClick={handleSignOut}
          style={{
            position: "absolute",
            top: -70,
            right: 10,
            backgroundColor: "red",
            color: "white",
            border: "none",
            padding: "5px 10px",
            cursor: "pointer",
          }}
        >
          Sign Out
        </button>
      </div>

      {/* Table */}
      <div
  className="table-wrapper"
  style={{
    maxHeight: "400px",
    overflowY: "auto",
    border: "2px solid #ccc",
    display: "block",
  }}
>
  <table style={{ width: "100%", borderCollapse: "collapse"}}>
    <thead>
      <tr>
        <th
          style={{
            position: "sticky",
            top: 0,
            backgroundColor: "#fff",
            border: "2px solid #ccc",
            padding: "8px",
            textAlign: "center",
            zIndex: 1,
          }}
        >
          QR Data
        </th>
        <th
          style={{
            position: "sticky",
            top: 0,
            backgroundColor: "#fff",
            border: "2px solid #ccc",
            padding: "8px",
            textAlign: "center",
            zIndex: 1
          }}
        >
          Lat
        </th>
        <th
          style={{
            position: "sticky",
            top: 0,
            backgroundColor: "#fff",
            border: "2px solid #ccc",
            padding: "8px",
            textAlign: "center",
            zIndex: 1
          }}
        >
          Lon
        </th>
        <th
          style={{
            position: "sticky",
            top: 0,
            backgroundColor: "#fff",
            border: "2px solid #ccc",
            padding: "8px",
            textAlign: "center",
            zIndex: 1
          }}
        >
          Date
        </th>
        <th
          style={{
            position: "sticky",
            top: 0,
            backgroundColor: "#fff",
            border: "2px solid #ccc",
            padding: "8px",
            textAlign: "center",
            zIndex: 1
          }}
        >
          Time
        </th>
        <th
          style={{
            position: "sticky",
            top: 0,
            backgroundColor: "#fff",
            border: "2px solid #ccc",
            padding: "8px",
            textAlign: "center",
            zIndex: 1
          }}
        >
          Image
        </th>
      </tr>
    </thead>
    <tbody>
      {scans.map((scan) => (
        <tr
          key={scan.key}
          style={{
            cursor: "pointer",
            textAlign: "center",
            backgroundColor: selectedData?.key === scan.key ? "#c9f5c9" : "white", // Highlight selected row
            transition: "background-color 0.2s ease-in-out",
          }}
          onClick={() => handleRowClick(scan)}
        >
          <td style={{ border: "2px solid #ccc", padding: "5px" }}>
            {truncateQRCode(scan.qrcodeData)}
          </td>
          <td style={{ border: "2px solid #ccc", padding: "5px" }}>
            {truncateCoordinates(scan.coordinates.x)}
          </td>
          <td style={{ border: "2px solid #ccc", padding: "5px" }}>
            {truncateCoordinates(scan.coordinates.y)}
          </td>
          <td style={{ border: "2px solid #ccc", padding: "5px" }}>
            {new Date(scan.timestamp).toLocaleDateString()}
          </td>
          <td style={{ border: "2px solid #ccc", padding: "5px" }}>
            {new Date(scan.timestamp).toLocaleTimeString()}
          </td>
          <td style={{ border: "2px solid #ccc", padding: "5px" }}>
                  {scan.imageUrl ? (
                    <button
                      onClick={(e) => {
                        e.stopPropagation(); // Prevent row selection when clicking the button
                        setIsModalOpen(true);
                        setSelectedData(scan);
                      }}
                      style={{ fontSize: "12px",backgroundColor: "#007bff", color: "white", border: "none", padding: "10px", cursor: "pointer" }}
                    >
                      View
                    </button>
                  ) : (
                    "No Image"
                  )}
          </td>
        </tr>
      ))}
    </tbody>
  </table>
</div>


{/* Display Selected Data Below the Table */}
{selectedData && (
        <div style={{ maxHeight: "200px", padding: "10px", border: "1px solid #ccc", backgroundColor: "#f9f9f9", fontSize: "15px", overflowY: "auto" }}>
          <h3>Selected Data</h3>
          <p>
            <strong>QR Data:</strong> {selectedData.qrcodeData}
          </p>
          <p>
            <strong>Latitude:</strong> {selectedData.coordinates.x}
          </p>
          <p>
            <strong>Longitude:</strong> {selectedData.coordinates.y}
          </p>
          {selectedData.completeAddress && (
            <p>
              <strong>Complete Address:</strong>{" "}
              <a href={`https://www.google.com/maps/search/${encodeURIComponent(selectedData.completeAddress)}`} target="_blank" rel="noopener noreferrer" style={{ color: "blue", textDecoration: "underline" }}>
                {selectedData.completeAddress}
              </a>
            </p>
          )}
        </div>
      )}

      {/* Image Modal */}
      {isModalOpen && selectedData?.imageUrl && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: "rgba(0, 0, 0, 0.7)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 1000,
          }}
        >
          <div style={{ position: "relative", backgroundColor: "#fff", padding: "20px", borderRadius: "10px" }}>
            <button
              onClick={() => setIsModalOpen(false)}
              style={{
                position: "absolute",
                top: "10px",
                right: "10px",
                backgroundColor: "red",
                color: "white",
                border: "none",
                padding: "5px 10px",
                cursor: "pointer",
              }}
            >
              X
            </button>
            <h3 style={{ textAlign: "center" }}>Scanned Image</h3>
            <img src={selectedData.imageUrl} alt="Scanned" style={{ maxWidth: "90vw", maxHeight: "80vh", borderRadius: "5px" }} />
          </div>
        </div>
      )}
    </div>
  );
};

export default ScannedData;
