import React, { useRef, useState } from "react";
import Webcam from "react-webcam";
// import { storage } from "../firebase"; // Storage import commented out
import { database } from "../firebase"; // Only using database
// import { ref as storageRef2, uploadBytes, getDownloadURL } from "firebase/storage";
import { ref as databaseRef, update } from "firebase/database";

const PictureCapture = ({ userID, uniqueKey, onBack }) => {
  const webcamRef = useRef(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [uploading, setUploading] = useState(false);

  const videoConstraints = {
    facingMode: "environment",
    width: 1280,
    height: 720,
  };

  const captureImage = () => {
    const imageSrc = webcamRef.current.getScreenshot();
    setCapturedImage(imageSrc);
  };

  const base64ToBlob = (base64Data) => {
    const byteCharacters = atob(base64Data.split(",")[1]);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    return new Blob([new Uint8Array(byteNumbers)], { type: "image/jpeg" });
  };

  // Uploading image to Firebase Storage is currently disabled
  /*
  const uploadImage = async () => {
    if (!capturedImage || !uniqueKey) {
      alert("No image captured or unique key missing!");
      return;
    }

    setUploading(true);

    try {
      const imageBlob = base64ToBlob(capturedImage);
      const storageRef = ref(
        storage,
        `images/${userID}/${uniqueKey}.jpg`
      );
      await uploadBytes(storageRef, imageBlob);

      const imagePath = `images/${userID}/${uniqueKey}.jpg`;
      const storageRefPath = storageRef2(storage, imagePath);
      const imageURL = await getDownloadURL(storageRefPath);

      const databasePath = `data/scans/${userID}/${uniqueKey}`;
      const databaseRefPath = databaseRef(database, databasePath);
      await update(databaseRefPath, { imageUrl: imageURL });

      alert("Image uploaded successfully!");
    } catch (error) {
      console.error("Error uploading image:", error);
      alert("Failed to upload the image. Please try again.");
    } finally {
      setUploading(false);
    }
  };
  */

  return (
    <div style={{ textAlign: "center" }}>
      <h2>Picture Capture</h2>

      {capturedImage ? (
        <div>
          <img
            src={capturedImage}
            alt="Captured"
            style={{ maxWidth: "100%", maxHeight: "300px" }}
          />
          <div style={{ marginTop: "10px" }}>
            <button onClick={() => setCapturedImage(null)}>Retake</button>
            {/* <button onClick={uploadImage} disabled={uploading}>
              {uploading ? "Uploading..." : "Upload Image"}
            </button> */}
          </div>
        </div>
      ) : (
        <div>
          <Webcam
            audio={false}
            ref={webcamRef}
            screenshotFormat="image/jpeg"
            videoConstraints={videoConstraints}
            style={{ width: "100%", maxHeight: "500px" }}
          />
          <button onClick={captureImage} style={{ marginTop: "10px" }}>
            Capture
          </button>
        </div>
      )}

      <button onClick={onBack} style={{ marginTop: "20px" }}>
        Back
      </button>
    </div>
  );
};

export default PictureCapture;
