import React, { useState, useEffect, useRef } from "react";
import { database } from "../firebase";
import { ref, set, serverTimestamp } from "firebase/database";
import { Html5Qrcode } from "html5-qrcode";

const Scanner = ({ user, onStopScan, setUniqueKey, setUserID }) => {
  const [message, setMessage] = useState("");
  const qrReaderRef = useRef(null);

  useEffect(() => {
    const getLocation = () =>
      new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
          timeout: 10000, // Timeout after 10s
        });
      });

    const startScanning = async () => {
      try {
        if (!navigator.geolocation) {
          setMessage("Geolocation is not supported by this browser.");
          return;
        }

        // Stop previous scanner if running
        if (qrReaderRef.current) {
          await qrReaderRef.current.stop();
          qrReaderRef.current = null;
        }

        const qrReader = new Html5Qrcode("reader");
        qrReaderRef.current = qrReader;

        await qrReader.start(
          { facingMode: "environment" },
          { fps: 10, qrbox: { width: 400, height: 400 } },
          async (decodedText) => {
            console.log("Decoded QR Data:", decodedText);

            try {
              const position = await getLocation();
              const latitude = position.coords.latitude;
              const longitude = position.coords.longitude;

              await qrReader.stop();
              qrReaderRef.current = null;

              const userPath = user.email.replace(".", "-");
              const sanitizedData = decodedText.replace(/[^a-zA-Z0-9_-]/g, "-");
              const timestamp = Date.now();
              const uniqueKey = `${sanitizedData}(${timestamp})`;
              const scanRef = ref(database, `data/scans/${userPath}/${uniqueKey}`);

              const scanData = {
                coordinates: { x: latitude, y: longitude },
                qrcodeData: decodedText,
                timestamp: serverTimestamp(),
                completeAddress: null,
              };

              await set(scanRef, scanData);
              console.log("Data saved successfully");
              setUniqueKey(uniqueKey);
              setUserID(userPath);
              onStopScan();
            } catch (locationError) {
              console.error("Location error:", locationError);
              if (locationError.code === 1) {
                setMessage("Location permission denied. Please allow location access.");
              } else if (locationError.code === 2) {
                setMessage("Location unavailable. Please check your GPS settings.");
              } else if (locationError.code === 3) {
                setMessage("Location request timed out. Try again.");
              } else {
                setMessage("Failed to retrieve location.");
              }

              await qrReader.stop();
              qrReaderRef.current = null;
            }
          },
          (scanError) => {
            console.log("QR Scan Error:", scanError);
          }
        );

        console.log("Scanning started...");
      } catch (err) {
        console.error("Scanner init error:", err.message);
        setMessage("Unable to start scanner. Check camera and location permissions.");
      }
    };

    startScanning();

    return () => {
      if (qrReaderRef.current) {
        qrReaderRef.current
          .stop()
          .then(() => {
            qrReaderRef.current = null;
          })
          .catch((err) => console.error("Error stopping scanner:", err));
      }
    };
  }, [user, onStopScan, setUniqueKey, setUserID]);

  return (
    <div>
      <h2 style={{ textAlign: "center" }}>QR Code Scanner</h2>
      {message && (
        <div
          style={{
            color: "red",
            textAlign: "center",
            marginBottom: "10px",
            fontWeight: "bold",
          }}
        >
          {message}
        </div>
      )}
      <div id="reader" style={{ width: "100%", height: "300px" }}></div>
    </div>
  );
};

export default Scanner;
